/**
 * Spoken prompts, played from pre-recorded files.
 *
 * The recordings are generated by scripts/generate_audio.py from data/phrases.json — the same
 * manifest this module reads, so the wording and the clips cannot drift apart. A test recomputes a
 * sha256 for every clip and compares it with the manifest, because an existence check cannot tell a
 * correct clip from a swapped one, an empty one, or one generated from last week's wording.
 *
 * Playback is dumb on purpose: no queue, no timing, no synthesis. But `say` returns a promise, and
 * that matters — the first version returned nothing and the prompt for the next question interrupted
 * the praise for the last answer in the same tick, so the child never heard "well done".
 */

import manifest from '../data/phrases.json';

export type Locale = 'en' | 'yue' | 'zh';

export interface Phrase {
  key: string;
  en: string;
  /** How it is said. */
  yue: string;
  /** How it is written: 三時十五分 rather than 三點三. */
  zh: string;
}

/** Every phrase the app can say. */
export const PHRASES: readonly Phrase[] = [...manifest.ui, ...manifest.chrono] as Phrase[];

/** The bit of HTMLAudioElement this needs, so a test can supply one. */
export interface Sound {
  play: () => Promise<void>;
  pause: () => void;
  /**
   * Register the "finished" callback. A method rather than an `onended` property because
   * HTMLAudioElement's `onended` takes an Event and a `this`, and does not satisfy a bare `() => void`.
   */
  onEnded: (callback: () => void) => void;
}

export type SoundFactory = (url: string) => Sound;

/** How long to wait for a clip that never reports ending before carrying on regardless. */
export const SOUND_TIMEOUT_MS = 4000;

const byKey = new Map(PHRASES.map((phrase) => [phrase.key, phrase]));

export function phraseFor(key: string): Phrase | undefined {
  return byKey.get(key);
}

export function phraseText(key: string, locale: Locale): string | undefined {
  return byKey.get(key)?.[locale];
}

export interface ClipRecord {
  /** The words this clip was generated from. */
  text: string;
  sha256: string;
}

/** The recorded clips, as recorded by the generator: locale → key → what it says and its hash. */
export const CLIPS = (manifest.clips ?? {}) as Record<Locale, Record<string, ClipRecord>>;

/**
 * The clip for a clock face.
 *
 * Cantonese names the hour just passed, so 3:45 is 三點九 — `qto-3`, not `qto-4`. The table in
 * data/phrases-yue.csv was reviewed for exactly this, so the mapping follows it rather than the
 * English reading.
 *
 * These keys are used by `set` tasks ("make three o'clock"), which have no screen yet, and by the
 * five-minute tiers. They are recorded now so the voice exists when the screens do.
 */
export function chronoKeyFor(time: { hour: number; minute: number }): string | undefined {
  const hour = time.hour % 12 === 0 ? 12 : time.hour % 12;
  switch (time.minute) {
    case 0:
      return `oclock-${hour}`;
    case 15:
      return `qpast-${hour}`;
    case 30:
      return `half-${hour}`;
    case 45:
      return `qto-${hour}`;
    default:
      return undefined; // five-minute and exact-minute levels arrive with their own recordings
  }
}

export function audioUrl(key: string, locale: Locale): string {
  return `/audio/${locale}/${key}.mp3`;
}

/** What to say for an item. Reading gets the question; the rest get a nudge. */
/**
 * The one prompt worth speaking. A read item's question is the face, so the app asks it aloud; every
 * other task is answered by touching the screen, and a generic "have a go" ten times a round teaches
 * a child to stop listening.
 */
export function promptKeyFor(item: { task: string }): string | undefined {
  return item.task === 'read' ? 'prompt-read' : undefined;
}

export class Speaker {
  private muted = false;
  private current: Sound | undefined;
  /** Bumped on every new sound, so a late `then` from an interrupted clip cannot speak over it. */
  private generation = 0;

  constructor(
    private readonly make: SoundFactory,
    private locale: Locale = 'en',
  ) {}

  getLocale(): Locale {
    return this.locale;
  }

  setLocale(locale: Locale): void {
    this.locale = locale;
  }

  isMuted(): boolean {
    return this.muted;
  }

  setMuted(muted: boolean): void {
    this.muted = muted;
    if (muted) {
      this.current?.pause();
      this.generation += 1;
    }
  }

  /**
   * Say a phrase. Resolves when the clip has finished (or could not play), so the caller can put one
   * sound after another — which is how a verdict is heard before the next question is asked.
   */
  say(key: string | undefined): Promise<void> {
    if (this.muted || !key || !phraseFor(key)) return Promise.resolve();

    this.current?.pause();
    const sound = this.make(audioUrl(key, this.locale));
    this.current = sound;
    const mine = (this.generation += 1);

    return new Promise<void>((resolve) => {
      let done = false;
      const finish = (): void => {
        if (done) return;
        done = true;
        resolve();
      };

      sound.onEnded(finish);
      // a clip that never reports ending must not strand the sequence that follows it
      setTimeout(finish, SOUND_TIMEOUT_MS);

      // A browser refusing to autoplay is expected before the first tap, not an error to surface.
      void sound.play().catch(() => {
        if (mine === this.generation) this.current = undefined;
        finish();
      });
    });
  }
}
